async function main(ctx) {
  const resp = ctx.lastOutputOf('get_template') || {};
  const initialArgs = ctx.lastOutputOf('__initial__') || {};

  const connectorId = initialArgs.connectorId;
  const endpointName = initialArgs.endpointName;

  const body = resp.body;
  if (!body || body.success !== true) {
    return {
      success: false,
      error: 'Failed to get connector template action',
      connectorId,
      endpointName,
      status: resp.status,
      body,
      message: `Failed to fetch action '${endpointName}' from connector template '${connectorId}'`
    };
  }

  const data = body.data ?? {};
  const endpoint = data.action ?? data.endpoint ?? data;

  if (!endpoint || typeof endpoint !== 'object') {
    return {
      success: false,
      error: 'Action payload missing',
      connectorId,
      endpointName,
      data,
      message: `Action '${endpointName}' payload missing in response`
    };
  }

  return {
    success: true,
    endpoint,
    connectorId,
    endpointName,
    message: `Successfully retrieved action '${endpointName}' from connector template '${connectorId}'`
  };
}
